fn replace_once(source:&mut String,from:&str,to:&str,label:&str){let count=source.matches(from).count();assert_eq!(count,1,"build_v1190b patch {label} expected one match, found {count}");*source=source.replacen(from,to,1);}
fn insert_before_once(source:&mut String,anchor:&str,insertion:&str,label:&str){let count=source.matches(anchor).count();assert_eq!(count,1,"build_v1190b patch {label} expected one anchor, found {count}");let at=source.find(anchor).expect("build_v1190b insertion anchor");source.insert_str(at,insertion);}

